import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"Installation.md","filePath":"Installation.md","lastUpdated":1788563284000}'),o={name:"Installation.md"};function r(s,t,d,l,h,p){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Grab the newest build from the <a href="https://github.com/xeidral/anisphere/releases/latest" target="_blank" rel="noreferrer">releases page</a> and pick the file for your platform.</p><table tabindex="0"><thead><tr><th>Platform</th><th>File</th><th>Notes</th></tr></thead><tbody><tr><td>Windows</td><td><code>.exe</code> installer, or <code>.msi</code></td><td>Windows 11 already has the WebView2 runtime. On Windows 10 the installer fetches it</td></tr><tr><td>macOS</td><td><code>.dmg</code></td><td>Drag it to Applications</td></tr><tr><td>Linux</td><td><code>.AppImage</code></td><td>Mark it executable and run it, no install needed</td></tr><tr><td>Linux, Debian and Ubuntu</td><td><code>.deb</code></td><td><code>sudo apt install ./anisphere_*.deb</code></td></tr></tbody></table><h2 id="unsigned-builds" tabindex="-1">Unsigned builds <a class="header-anchor" href="#unsigned-builds" aria-label="Permalink to &quot;Unsigned builds&quot;">​</a></h2><p>The releases are signed for the auto-updater, not with a paid operating system certificate, so both Windows and macOS will warn you the first time.</p><p><strong>Windows.</strong> SmartScreen shows &quot;Windows protected your PC&quot;. Choose More info, then Run anyway.</p><p><strong>macOS.</strong> Gatekeeper says the developer cannot be verified. Open System Settings, go to Privacy and Security, and choose Open Anyway next to the AniSphere entry. Or right-click the app and choose Open.</p><p>If that is not acceptable to you, building from source is the alternative and takes about ten minutes. See <a href="./Development-Setup">Development Setup</a>.</p><h2 id="first-start" tabindex="-1">First start <a class="header-anchor" href="#first-start" aria-label="Permalink to &quot;First start&quot;">​</a></h2><p>The first run downloads the catalogue, which is a single file of roughly forty megabytes from the <a href="https://github.com/manami-project/anime-offline-database" target="_blank" rel="noreferrer">manami project</a>. That is the only thing that holds the app up, and it takes well under a minute on a normal connection.</p><p>Nothing else has to finish. Descriptions, artwork and episode counts are fetched from AniList for the titles a page is showing, a page at a time, so the app is usable the moment the catalogue is written and there is no second wait to sit through. See <a href="./Getting-Started">Getting Started</a>.</p><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>AniSphere checks for updates on launch and installs them quietly when you agree. Nothing is downloaded without the signature being verified against a key compiled into the build.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><p>Use the normal uninstaller on Windows, delete the app on macOS, or remove the package on Linux. Your data is separate, and where to find it is in <a href="./Data-Privacy-And-Security">Data, Privacy and Security</a>.</p>',15)])])}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
